FormulaFieldDefinitions.FormulaFieldDefinition:
WhilePrintingRecords;
NumberVar OpCrAmt;
NumberVar OpDrAmt;
if OpCrAmt - OpDrAmt > 0 then
  {@TranCrAmt} + OpCrAmt - OpDrAmt + {@CloseCrAmt}
else
  {@TranCrAmt} + {@CloseCrAmt};

WhilePrintingRecords;
NumberVar OpCrAmt;
NumberVar OpDrAmt;
if OpCrAmt - OpDrAmt <= 0 then
 {@TranDrAmt} + OpDrAmt - OpCrAmt + {@CloseDrAmt}
else
  {@TranDrAmt} + {@CloseDrAmt};

WhilePrintingRecords;
NumberVar BalAmt;
BalAmt :=  BalAmt + {@CrAmt} - {@DrAmt};
BalAmt;

EvaluateAfter ({@BalAmt});
WhilePrintingRecords;
NumberVar BalAmt;
if BalAmt > 0 then
  'Cr'
else if BalAmt < 0 then
  'Dr';

WhilePrintingRecords;
NumberVar BalAmt ;
NumberVar TranCrAmt;
NumberVar TranDrAmt;
if BalAmt  <= 0 then
   Abs(BalAmt)

WhilePrintingRecords;
NumberVar BalAmt ;
NumberVar TranCrAmt;
NumberVar TranDrAmt;
if BalAmt > 0 then
   abs(BalAmt);

WhilePrintingRecords;
if OnFirstRecord or {AC_DATA.AC_CODE} <> Previous({AC_DATA.AC_CODE})  then
(
NumberVar BalAmt := 0 ;
booleanVar OpBalPrint := False;
NumberVar TranCrAmt:=0;
NumberVar TranDrAmt:=0;
NumberVar OpCrAmt :=0 ;
NumberVar OpDrAmt := 0;
NumberVar IntTotSum := 0;
NumberVar SrNo := SrNo + 1;
)

WhilePrintingRecords;
NumberVar IntTotSum;
IntTotSum :=  IntTotSum +{@interest};
IntTotSum;

WhilePrintingRecords;
dateVar NextDate;
if {@GroupDate} >= {@FromDate} then
    if OnLastRecord or {AC_DATA.AC_CODE} <> Next({AC_DATA.AC_CODE}) then
        NextDate := {@ToDate}
    else
        NextDate := Next({@GroupDate});

WhilePrintingRecords;
NumberVar TranDrAmt;
NumberVar TranCrAmt;
NumberVar OpDrAmt;
NumberVar OpCrAmt;
NumberVar TotIntAmt;
if not (TranDrAmt <> 0 Or TranCrAmt <> 0 or (OpCrAmt - OpDrAmt) = 0) then
    TotIntAmt := TotIntAmt + {@OpInterest};

WhilePrintingRecords;
NumberVar BalAmt;
if BalAmt > 0 then
  'Cr'
else if BalAmt < 0 then
  'Dr';

WhilePrintingRecords;
booleanVar OpBalPrint;
if {AC_DATA.VCH_DATE} >= {@FromDate} then
OpBalPrint := True;

WhilePrintingRecords;
NumberVar BalAmt;
if BalAmt > 0 then
   BalAmt
else
  0;

WhilePrintingRecords;
NumberVar BalAmt;
if BalAmt < 0 then
   BalAmt
else
  0;

whileprintingrecords;
NumberVar BalAmt;
NumberVar Days;
BalAmt * Days * -1;

EvaluateAfter ({@Balance});
whileprintingrecords;
NumberVar Product;
NumberVar BalAmt;
NumberVar Days;
Product := BalAmt * {@Days} * -1;
Product;

//WhilePrintingRecords;
//NumberVar opg ;
//NumberVar cpg  := Pagenumber;
//booleanvar zprn;
//zprn=false;

//if pagenumber=1 then
   //( zprn  := true;
//    opg := Pagenumber)
//else
//    if opg <> cpg then
//       ( zprn := false;
//         opg := Pagenumber)
//    else
//       (zprn  := true;
//        opg := Pagenumber);
//
//
//zprn;

whileprintingrecords;
if not InRepeatedGroupHeader then
    NumberVar TotIntAmt := 0;

whileprintingrecords;
BooleanVar OpBalPrint;
EvaluateAfter ({@OpInterest});
//if {AC_DATA.VCH_DATE} <= {@FromDate} then
if Not ({@GroupDate} < {@FromDate} or OpBalPrint = True) then
    NumberVar TotIntAmt := {@OpInterest};

WhilePrintingRecords;
NumberVar TotIntAmt;
if {@GroupDate} >= {@FromDate} then
    if OnLastRecord or {@GroupDate} <> Next({@GroupDate}) then
        TotIntAmt := TotIntAmt + {@Interest};
TotIntAmt;

WhilePrintingRecords;
NumberVar SrNo;
//if not InRepeatedGroupHeader then
//SrNo := SrNo + 1;
SrNo;

WhilePrintingRecords;
NumberVar TranCrAmt;
NumberVar TranDrAmt;
NumberVar OpCrAmt;
NumberVar OpDrAmt;
if {AC_DATA.VCH_DATE} >= {@FromDate} then
(
  TranCrAmt := TranCrAmt + {@CrAmt};
  TranDrAmt := TranDrAmt + {@DrAmt};
)
else
(
  OpCrAmt := OpCrAmt + {@CrAmt};
  OpDrAmt := OpDrAmt + {@DrAmt};
)

SectionAreaConditionFormulas.EnableSuppress:
WhilePrintingRecords;
BooleanVar HeaderPrint;
if HeaderPrint = True then True;
